<?php

declare(strict_types=1);

namespace KitgenixImageOptimizer\Core;

defined( 'ABSPATH' ) || exit;

/**
 * Serves WebP sidecar files to supporting browsers by wrapping <img> elements
 * in <picture><source type="image/webp"> on the frontend.
 *
 * Sidecars are named <original-file>.webp (e.g. photo.jpg.webp) and are
 * generated by Optimizer::optimize_file() when convert_to_webp is enabled.
 */
final class Webp_Delivery {

	public static function init(): void {
		if ( ! Settings::convert_to_webp() ) {
			return;
		}

		// Wrap <img> tags in post content and featured images.
		add_filter( 'the_content', [ self::class, 'wrap_content_images' ], 99 );
		add_filter( 'post_thumbnail_html', [ self::class, 'wrap_content_images' ], 99 );

		// Wrap wp_get_attachment_image() output.
		add_filter( 'wp_get_attachment_image', [ self::class, 'wrap_single_image' ], 99 );
	}

	/**
	 * Scan an HTML block for <img> tags and wrap eligible ones with <picture>.
	 */
	public static function wrap_content_images( string $html ): string {
		return (string) preg_replace_callback(
			'/<img\b[^>]*>/i',
			static function ( array $match ): string {
				return self::img_to_picture( $match[0] );
			},
			$html
		);
	}

	/**
	 * Wrap a single <img> string returned by wp_get_attachment_image().
	 */
	public static function wrap_single_image( string $html ): string {
		return self::img_to_picture( $html );
	}

	/**
	 * Attempt to wrap a single <img> tag with a <picture> element.
	 * Returns the original tag unchanged when no .webp sidecar is found.
	 */
	private static function img_to_picture( string $img_html ): string {
		if ( ! preg_match( '/\bsrc=["\']([^"\']+)["\']/', $img_html, $src_m ) ) {
			return $img_html;
		}

		$src_url = $src_m[1];

		// Only process JPEG and PNG source images.
		if ( ! preg_match( '/\.(jpe?g|png)(\?[^"\']*)?$/i', $src_url ) ) {
			return $img_html;
		}

		$upload_dir = wp_upload_dir();
		$base_url   = trailingslashit( $upload_dir['baseurl'] );
		$base_dir   = trailingslashit( $upload_dir['basedir'] );

		// Normalise both URLs to the same scheme so http/https mismatches don't break matching.
		$src_normalised  = set_url_scheme( $src_url );
		$base_normalised = set_url_scheme( $base_url );

		// Only process images hosted in the uploads directory.
		if ( ! str_starts_with( $src_normalised, $base_normalised ) ) {
			return $img_html;
		}

		// Derive the filesystem path and check for a .webp sidecar.
		$src_rel      = (string) strtok( substr( $src_normalised, strlen( $base_normalised ) ), '?' );
		$src_webp_abs = $base_dir . $src_rel . '.webp';

		if ( ! file_exists( $src_webp_abs ) ) {
			return $img_html;
		}

		// Build the WebP srcset — try to convert all responsive entries first.
		$webp_srcset = '';
		if ( preg_match( '/\bsrcset=["\']([^"\']+)["\']/', $img_html, $ss_m ) ) {
			$webp_srcset = self::convert_srcset_to_webp( $ss_m[1], $base_url, $base_dir );
		}

		// Fall back to the single main image WebP URL when no full srcset is available.
		if ( '' === $webp_srcset ) {
			$webp_srcset = esc_attr( $base_url . $src_rel . '.webp' );
		}

		// Carry the sizes attribute through to <source> for correct responsive behaviour.
		$sizes_attr = '';
		if ( preg_match( '/\bsizes=["\']([^"\']+)["\']/', $img_html, $sz_m ) ) {
			$sizes_attr = ' sizes="' . esc_attr( $sz_m[1] ) . '"';
		}

		return '<picture><source type="image/webp" srcset="' . $webp_srcset . '"' . $sizes_attr . '>' . $img_html . '</picture>';
	}

	/**
	 * Convert a JPEG/PNG srcset string to its WebP equivalent.
	 *
	 * Each descriptor URL is mapped to <url>.webp. Returns an empty string
	 * if any entry is missing a sidecar (caller falls back to single-src WebP).
	 */
	private static function convert_srcset_to_webp( string $srcset, string $base_url, string $base_dir ): string {
		$parts            = array_filter( array_map( 'trim', explode( ',', $srcset ) ) );
		$webp_parts       = [];
		$base_url_norm    = set_url_scheme( $base_url );
		$base_url_norm_ln = strlen( $base_url_norm );

		foreach ( $parts as $part ) {
			$segs = (array) preg_split( '/\s+/', trim( $part ), 2 );
			$url  = (string) ( $segs[0] ?? '' );

			if ( '' === $url ) {
				continue;
			}

			$desc     = isset( $segs[1] ) ? ' ' . $segs[1] : '';
			$url_norm = set_url_scheme( $url );

			// Non-local URL — bail and let caller use the single-src fallback.
			if ( ! str_starts_with( $url_norm, $base_url_norm ) ) {
				return '';
			}

			$rel      = (string) strtok( substr( $url_norm, $base_url_norm_ln ), '?' );
			$webp_abs = $base_dir . $rel . '.webp';

			if ( ! file_exists( $webp_abs ) ) {
				return '';
			}

			$webp_parts[] = esc_attr( $base_url . $rel . '.webp' ) . $desc;
		}

		return implode( ', ', $webp_parts );
	}
}
